import {api,hero,upload,removeMedia,signIn,signInPassword,signOut,supabase,configured} from './api.js';
import {occupations,bodyTypes,lifestyles,trainingStyles} from './model.js';
import {preparePhoto} from './album.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=s=>{try{const u=new URL(s,location.href);return ['https:','http:'].includes(u.protocol)?esc(u.href):'';}catch{return '';}};
const paths={discover:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5z"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',messages:'<path d="M21 11.5a8 8 0 0 1-12 7L3 21l2-6a8 8 0 1 1 16-3.5Z"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v2"/>',settings:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',sliders:'<path d="M4 6h16M4 12h16M4 18h16"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.discover}</svg>`;
const cities=['TP. Hồ Chí Minh','Hà Nội','Đà Nẵng','Cần Thơ','Hải Phòng','Huế','Nha Trang','Đà Lạt','Khác'];
const intents=['Mối quan hệ nghiêm túc','Hẹn hò thoải mái','Trò chuyện rồi tìm hiểu'],training=trainingStyles;
const defaults=()=>({city:'all',occupation:'all',intent:'all',bodyType:'all',training:'all',lifestyle:'all',minAge:18,maxAge:80,query:'',radius:0});
let filters=defaults(),filterOpen=false,route='discover',me=null,session=null,items=[],contacts=[],blocked=[],chatId='',heroData=null,toastTimer,searchTimer,requestId=0,renderId=0,authRunning=false,lastAuthToken='',busy=false,gallery=[],galleryIndex=0;
const cache=new Map();
function options(arr,current,all){return (all?`<option value="all">${esc(all)}</option>`:'')+arr.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5500);}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-inner"><div class="modal-header"><h2>${esc(title)}</h2><button class="close-button" data-action="close" aria-label="Đóng">×</button></div><div class="info-content">${body}</div></div>`;if(!$('#modal').open)$('#modal').showModal();}
function empty(title,body){return `<div class="empty">${icon('discover')}<h3>${esc(title)}</h3><p>${esc(body)}</p></div>`;}
function photo(p){return p.photos?.find(x=>x.kind==='image')?.src||'';}
function avatar(p,cls=''){return photo(p)?`<img class="${cls}" src="${safeURL(photo(p))}" alt="${esc(p.name)}" referrerpolicy="no-referrer">`:`<span class="avatar-letter ${cls}">${esc(p?.name?.[0]||'B')}</span>`;}
function nav(){const links=[['discover','discover','Khám phá'],['liked','heart','Kết nối'],['messages','messages','Tin nhắn'],['profile','profile','Hồ sơ của tôi'],['settings','settings','Riêng tư']];if(me?.admin)links.push(['admin','settings','Quản trị']);const html=links.map(([id,i,t])=>`<button class="nav-button ${route===id?'active':''}" data-nav="${id}" ${route===id?'aria-current="page"':''}>${icon(i)}<span class="nav-label">${t}</span></button>`).join('');$('#nav').innerHTML=html;$('#mobile-nav').innerHTML=html;document.querySelectorAll('.user-mini .avatar-letter,.top-profile .avatar-letter').forEach(el=>el.innerHTML=photo(me||{})?`<img src="${safeURL(photo(me))}" alt="Ảnh đại diện của bạn">`:esc(me?.name?.[0]||'B'));}
function go(next){if(next==='admin'){location.href='admin.html';return;}if(!session){showAuth();return;}if(location.hash===`#${next}`){route=next;render();}else location.hash=next;window.scrollTo({top:0,behavior:'instant'});}
function card(p){cache.set(p.id,p);return `<article class="profile-card"><div class="card-image" data-open="${p.id}" role="button" tabindex="0" aria-label="Xem hồ sơ ${esc(p.name)}"><img src="${safeURL(photo(p))}" alt="${esc(p.name)}" loading="lazy"><span class="photo-count">▧ ${p.photos?.length||0}</span><button class="like-button ${me?.likes?.includes(p.id)?'liked':''}" data-like="${p.id}" aria-label="Thích ${esc(p.name)}" aria-pressed="${!!me?.likes?.includes(p.id)}">${icon('heart')}</button><div class="card-title"><h3>${esc(p.name)}<span>, ${p.age}</span></h3><p>${icon('pin')}${esc(p.distance||p.city)}</p></div></div><div class="card-body"><div class="job">${esc(p.occupation||'Một người cùng gu')}<span>·</span><span class="training-label">${esc(p.bodyType)}</span></div><div class="tags">${[p.training,p.lifestyle].filter(Boolean).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="card-footer"><span>${esc(p.intent)}</span><button data-open="${p.id}">Làm quen ↗</button></div></div></article>`;}
function discovery(){return `<section class="hero"><img class="hero-photo" src="${safeURL(heroData?.src||'assets/long-1.jpg')}" alt="${esc(heroData?.alt||'Sức hút từ cuộc sống đời thường')}"><div class="hero-copy"><span class="eyebrow">SỨC HÚT KHÔNG CHỈ Ở PHÒNG GYM</span><h1>Cùng gu hình thể.<br><em>Hợp gu hẹn hò.</em></h1><p>Từ phòng tập đến những nhịp sống đời thường.<br>Tìm người bạn thấy thu hút, theo cách của riêng mình.</p><button class="button primary" data-action="explore">Tìm người cùng tần số ${icon('arrow')}</button></div><div class="hero-label">RẮN RỎI. CHÂN THÀNH. CÙNG GU.</div></section><section id="discover-section"><div class="heading-row"><div><h2>Gu của bạn, nhiều hơn một kiểu.</h2><p>Nghề nghiệp và vóc dáng là hai lựa chọn riêng biệt.</p></div><div class="search">${icon('search')}<input id="query" type="search" placeholder="Tên, nghề, sở thích…" value="${esc(filters.query)}" aria-label="Tìm hồ sơ theo tên nghề nghiệp hoặc sở thích"></div></div><div class="nearby-panel"><div><b>Người cùng gu ở gần</b><p>Chia sẻ vị trí khi bạn muốn. Chỉ hiển thị khoảng cách gần đúng.</p></div><button class="button secondary" data-action="nearby">${me?.nearbyEnabled?'Cập nhật vị trí':'Bật tìm ở gần'}</button><select id="radius-filter" aria-label="Khoảng cách"><option value="0">Mọi khoảng cách</option>${[5,10,25,50,100].map(n=>`<option value="${n}" ${filters.radius===n?'selected':''}>Trong ${n} km</option>`).join('')}</select></div><div class="filters"><div class="filter-select"><select id="city-filter" aria-label="Lọc khu vực">${options(cities,filters.city,'Tất cả khu vực')}</select></div><div class="filter-select"><select id="occupation-filter" data-filter="occupation" aria-label="Lọc nghề nghiệp">${options(occupations,filters.occupation,'Tất cả nghề nghiệp')}</select></div><div class="filter-select"><select id="intent-filter" aria-label="Lọc mục đích kết nối">${options(intents,filters.intent,'Mong muốn kết nối')}</select></div><button class="filter-button" data-action="toggle-filters" aria-expanded="${filterOpen}" aria-controls="advanced-filters">${icon('sliders')}Lọc thêm</button><button class="filter-reset" data-action="reset-filters">Đặt lại</button></div><div class="filter-detail advanced-filters" id="advanced-filters" ${filterOpen?'':'hidden'}><div class="range-heading"><span>Độ tuổi mong muốn</span><strong id="age-value">${filters.minAge}–${filters.maxAge} tuổi</strong></div><div class="age-fields"><label for="min-age-filter">Từ<input id="min-age-filter" type="range" min="18" max="80" value="${filters.minAge}"></label><label for="age-filter">Đến<input id="age-filter" type="range" min="18" max="80" value="${filters.maxAge}"></label></div><div class="advanced-selects"><div class="field"><label for="training-filter">Cách vận động</label><select id="training-filter" data-filter="training">${options(training,filters.training,'Không giới hạn')}</select></div><div class="field"><label for="lifestyle-filter">Lối sống</label><select id="lifestyle-filter" data-filter="lifestyle">${options(lifestyles,filters.lifestyle,'Không giới hạn')}</select></div></div></div><div class="filter-label">VÓC DÁNG BẠN THÍCH <span>Thông tin do người dùng tự mô tả</span></div><div class="interest-tabs" aria-label="Vóc dáng">${['all',...bodyTypes].map(t=>`<button class="chip ${filters.bodyType===t?'active':''}" data-body="${t}" aria-pressed="${filters.bodyType===t}">${t==='all'?'Tất cả vóc dáng':t}</button>`).join('')}</div><div id="active-filters" class="active-filters"></div><div class="discovery-summary"><span id="results-count" class="results-label" role="status" aria-live="polite"></span><span>Không cần tập gym để có sức hút riêng.</span></div><div id="profile-results" class="profile-grid"></div><button class="button secondary" data-action="more" id="load-more" hidden style="margin-top:24px">Xem thêm</button></section><div class="tip-banner">${icon('settings')}<div><h3>Sức hút bắt đầu từ sự tôn trọng.</h3><p>Hỏi trước khi chia sẻ ảnh riêng tư. Tôn trọng ranh giới và lựa chọn của nhau.</p></div><button class="text-button" data-action="safety">Tìm hiểu thêm ↗</button></div>`;}
async function results(append=false){
 const rid=++requestId;if(!$('#profile-results'))return;
 if(!session){$('#profile-results').innerHTML=empty('Một kết nối mới bắt đầu từ đây.','Đăng nhập để gặp những người cùng gu.');$('#results-count').textContent='Khám phá cộng đồng';return;}
 if(!append)$('#profile-results').innerHTML=empty('Đang tìm người cùng gu…','');
 try{const found=await api('discover',{...filters,offset:append?items.length:0});if(rid!==requestId||!$('#profile-results'))return;items=append?[...items,...found]:found;
 $('#profile-results').innerHTML=items.length?items.map(card).join(''):empty('Chưa tìm thấy người phù hợp.','Thử mở rộng khoảng cách hoặc bỏ bớt điều kiện lọc.');$('#results-count').textContent=`${items.length} hồ sơ`;$('#load-more').hidden=found.length<48||items.length>=528;
 const active=Object.entries(filters).filter(([k,v])=>['city','occupation','intent','training','lifestyle','bodyType'].includes(k)&&v!=='all');$('#active-filters').innerHTML=active.map(([k,v])=>`<button class="active-filter" data-clear-filter="${k}">${esc(v)} ×</button>`).join('');
 }catch(e){if(rid!==requestId||!$('#profile-results'))return;$('#profile-results').innerHTML=empty('Chưa tải được hồ sơ.',e.message);$('#results-count').textContent='';}
}
function field(label,name,value,type='text',extra=''){return `<div class="field"><label for="my-${name}">${label}</label><input id="my-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function selectField(label,name,arr,value,optional=false){return `<div class="field"><label for="my-${name}">${label}</label><select id="my-${name}" name="${name}">${optional?'<option value="">Chưa chia sẻ</option>':`<option value="" disabled ${value?'':'selected'}>Chọn một mục</option>`}${options(arr,value)}</select></div>`;}
function profilePage(){if(!me)return empty('Đang mở hồ sơ…','');return `<div class="section-head"><h1>Hồ sơ của tôi</h1><p>Một chút về hình thể. Nhiều hơn về con người bạn.</p></div><section class="profile-editor"><div class="profile-intro">${avatar(me,'large')}<div><h2>${esc(me.name||'Tên của bạn')}</h2><p>${me.complete?'Hồ sơ đã hoàn thiện':'Thêm thông tin để mọi người biết bạn'}</p></div></div><form id="profile-form"><div class="form-grid">${field('Tên hiển thị','name',me.name,'text','required minlength="2" maxlength="40"')}${field('Tuổi · từ 18 trở lên','age',me.age||'','number','required min="18" max="80" step="1"')}${selectField('Khu vực','city',cities,me.city)}${selectField('Mong muốn kết nối','intent',intents,me.intent)}${selectField('Nghề nghiệp (tùy chọn)','occupation',occupations,me.occupation,true)}${selectField('Vóc dáng tự mô tả (tùy chọn)','bodyType',bodyTypes,me.bodyType,true)}${selectField('Lối sống (tùy chọn)','lifestyle',lifestyles,me.lifestyle,true)}${selectField('Cách vận động (tùy chọn)','training',training,me.training,true)}<div class="field full"><label for="my-bio">Một chút về bạn</label><textarea id="my-bio" name="bio" required minlength="20" maxlength="400" placeholder="Những điều bạn thích, một buổi hẹn lý tưởng…">${esc(me.bio)}</textarea><p class="fine-print">20–400 ký tự. Hãy giữ địa chỉ nhà và số điện thoại cho riêng mình.</p></div></div><div class="form-actions"><button class="button primary">Lưu hồ sơ ↗</button></div></form></section><section class="album-manager">${albumManager()}</section>`;}
function mediaElement(m,controls=false){return m.kind==='video'?`<video src="${safeURL(m.src)}" ${controls?'controls':''} preload="metadata" playsinline aria-label="${esc(m.caption||'Video của thành viên')}"></video>`:`<img src="${safeURL(m.src)}" alt="${esc(m.caption||'Ảnh của thành viên')}" loading="lazy">`;}
function albumManager(){const list=me.photos||[],count=list.filter(x=>x.kind==='image').length,videos=list.length-count;return `<div class="heading-row"><div><span class="eyebrow">MỘT GÓC ĐỜI THƯỜNG</span><h2>Ảnh & video của tôi</h2><p>${count}/10 ảnh · ${videos}/2 video</p></div><button class="button secondary" data-action="preview-self">Xem hồ sơ ↗</button></div><div class="own-photo-grid">${list.map(m=>`<article class="own-photo"><button class="own-photo-view" data-gallery-owner="self" data-media="${m.id}">${mediaElement(m)}${m.src===photo(me)?'<span class="cover-badge">Ảnh đại diện</span>':''}</button><form data-caption-form="${m.id}"><label for="caption-${m.id}">Chú thích</label><input id="caption-${m.id}" name="caption" maxlength="120" value="${esc(m.caption)}"><button class="text-button">Lưu chú thích</button></form><div class="photo-actions">${m.kind==='image'?`<button data-cover="${m.id}">Đặt đại diện</button>`:''}<button data-delete="${m.id}">Xóa</button></div></article>`).join('')}<button class="upload-tile" data-action="upload" ${busy?'disabled':''}><span>＋</span><b>${busy?'Đang tải lên…':'Thêm ảnh hoặc video'}</b><small>10 ảnh · 2 video</small></button></div><input id="media-input" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" multiple hidden><p class="fine-print" style="margin-top:18px">Ảnh tối đa 8 MB, video tối đa 20 MB. Chỉ đăng nội dung của bạn hoặc nội dung bạn có quyền sử dụng. Ảnh đại diện phải là ảnh của bạn.</p>`;}
function settings(){return `<div class="section-head"><h1>Riêng tư theo cách của bạn.</h1><p>Bạn chọn chia sẻ bao nhiêu và kết nối với ai.</p></div><div class="settings-grid"><section class="settings-panel"><h2>Hiển thị hồ sơ</h2><div class="setting-row"><div><label for="visible-setting">Cho phép người khác tìm thấy bạn</label><p>Ẩn hồ sơ cũng tạm ẩn ảnh và quyền bắt đầu trò chuyện.</p></div><input id="visible-setting" type="checkbox" class="switch" ${me?.visible?'checked':''}></div></section><section class="settings-panel"><h2>Vị trí của bạn</h2><p>${me?.nearbyEnabled?'Đang bật tìm người ở gần.':'Chưa chia sẻ vị trí.'} Vị trí tự hết hạn sau 24 giờ; không hiển thị tọa độ hoặc ghim chính xác.</p><button class="button secondary" data-action="location-off" style="margin-top:16px">Tắt và xóa vị trí</button></section><section class="settings-panel"><h2>Hồ sơ đã chặn</h2>${blocked.length?blocked.map(p=>`<div class="blocked-row"><span>${esc(p.name)}</span><button class="text-button" data-unblock="${p.id}">Bỏ chặn</button></div>`).join(''):'<p>Bạn chưa chặn ai.</p>'}</section><section class="settings-panel"><h2>Tài khoản</h2><p>Đăng xuất khi dùng chung thiết bị để bảo vệ tài khoản.</p><button class="button secondary" data-action="logout" style="margin-top:16px">Đăng xuất</button></section></div>`;}
async function render(){const rid=++renderId;++requestId;nav();if(route!=='discover'&&!session){showAuth();route='discover';}$('#page').innerHTML=route==='discover'?discovery():route==='profile'?profilePage():route==='settings'?settings():empty('Đang tải…','');
 try{
 if(route==='discover')await results();
 if(route==='liked'){const data=await api('liked');if(rid!==renderId)return;$('#page').innerHTML=`<div class="section-head"><h1>Kết nối của bạn</h1><p>Những người khiến bạn muốn tìm hiểu thêm.</p></div><div class="profile-grid">${data.length?data.map(card).join(''):empty('Chưa có lượt thích.','Ghé Khám phá và lưu người bạn muốn làm quen.')}</div>`;}
 if(route==='settings'){blocked=await api('blocked');if(rid===renderId)$('#page').innerHTML=settings();}
 if(route==='messages'){contacts=await api('contacts');if(rid!==renderId)return;contacts.forEach(p=>cache.set(p.id,p));if(!contacts.some(p=>p.id===chatId))chatId=contacts[0]?.id||'';$('#page').innerHTML=`<div class="section-head"><h1>Một câu chuyện mới.</h1><p>Bắt đầu bằng một câu hỏi chân thành.</p></div>${contacts.length?`<div class="message-layout"><aside class="conversation-list"><h2>KẾT NỐI CỦA BẠN</h2>${contacts.map(p=>`<button class="conversation ${p.id===chatId?'active':''}" data-chat="${p.id}">${avatar(p)}<span><b>${esc(p.name)}</b><small>${esc(p.city)}</small></span></button>`).join('')}</aside><section class="chat" id="chat-panel"></section></div>`:empty('Chưa có cuộc trò chuyện.','Gửi một lời chào từ hồ sơ bạn muốn tìm hiểu.')}`;await loadChat();}
 }catch(e){if(rid===renderId)toast(e.message);}
}
async function loadChat(){const id=chatId;if(!id||!$('#chat-panel'))return;const p=cache.get(id),messages=await api('messages',{id});if(chatId!==id||!$('#chat-panel'))return;$('#chat-panel').innerHTML=`<div class="chat-head">${avatar(p)}<div><b>${esc(p.name)}</b><small>${esc(p.city)}</small></div><button class="text-button" data-open="${id}">Hồ sơ ↗</button></div><div class="chat-log" id="chat-log" role="log">${messages.map(m=>`<div class="bubble ${m.sender_id===me.id?'me':''}">${esc(m.body)}<small>${new Date(m.created_at).toLocaleString('vi-VN',{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit'})}</small></div>`).join('')}</div><form class="chat-compose" id="message-form"><input name="text" maxlength="1000" required placeholder="Một lời chào, một kết nối mới…" aria-label="Tin nhắn"><button class="button primary">Gửi ↗</button></form><button class="text-button" data-action="refresh-chat">Làm mới cuộc trò chuyện</button>`;$('#chat-log').scrollTop=$('#chat-log').scrollHeight;}
async function details(id){const p=id==='self'?me:await api('profile',{id});cache.set(p.id,p);const list=p.photos||[];modal(`${p.name}, ${p.age||''}`,`<div class="self-preview-top">${avatar(p)}<div><p>${esc(p.city)}</p><p>${esc(p.occupation)}</p></div></div><div class="tags">${[p.bodyType,p.lifestyle,p.training,p.intent].filter(Boolean).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="bio">${esc(p.bio)}</p><h3>Ảnh & video của ${esc(p.name)}</h3><div class="album-thumbnails">${list.map(m=>`<button data-gallery-owner="${id}" data-media="${m.id}">${mediaElement(m)}<span>${esc(m.caption||'Một góc đời thường')}</span></button>`).join('')}</div>${id!=='self'?`<div class="action-row"><button class="button primary" data-intro="${p.id}">Gửi lời mở đầu ↗</button><button class="button secondary" data-like="${p.id}">${me.likes.includes(p.id)?'Bỏ thích':'Thích'}</button></div><div class="detail-controls"><button data-report="${p.id}">Báo cáo</button><button data-block="${p.id}">Chặn hồ sơ</button></div>`:''}`);}
function showGallery(owner,id){gallery=(owner==='self'?me:cache.get(owner))?.photos||[];galleryIndex=Math.max(0,gallery.findIndex(m=>m.id===id));paintGallery();if(gallery.length&&!$('#lightbox').open)$('#lightbox').showModal();}
function paintGallery(){if(!gallery.length)return;galleryIndex=(galleryIndex+gallery.length)%gallery.length;const m=gallery[galleryIndex];$('#lightbox-content').innerHTML=`<div class="lightbox-top"><b>${galleryIndex+1} / ${gallery.length}</b><button class="close-button" data-action="close-gallery" aria-label="Đóng">×</button></div><div class="lightbox-stage"><button class="photo-arrow previous" data-step="-1" aria-label="Ảnh trước">‹</button>${mediaElement(m,true)}<button class="photo-arrow next" data-step="1" aria-label="Ảnh tiếp">›</button></div><p class="lightbox-caption">${esc(m.caption)}</p>`;}
function authStep(login){$('#onboarding-track').classList.toggle('at-login',login);$('#welcome-step').inert=login;$('#login-step').inert=!login;$('#age-gate').scrollTop=0;if(login)$('#login-title').focus();}
function showAuth(){if(!$('#age-gate').open)$('#age-gate').showModal();authStep(false);if(!configured)$('#login-status').textContent='Đăng nhập sẽ mở khi dịch vụ sẵn sàng.';}
function reminder(){if(me?.complete)return;const list=[[me?.name?.trim().length>=2,'Tên hiển thị'],[me?.age>=18,'Tuổi từ 18 trở lên'],[me?.city,'Khu vực'],[me?.intent,'Mong muốn kết nối'],[me?.bio?.trim().length>=20,'Giới thiệu ít nhất 20 ký tự'],[photo(me||{}),'Ít nhất một ảnh của bạn']];$('#profile-checklist').innerHTML=list.map(([ok,label])=>`<li class="${ok?'done':''}">${ok?'✓':'○'} ${label}</li>`).join('');if(!$('#profile-reminder').open)$('#profile-reminder').showModal();}
async function refreshMe(){me=await api('me');nav();}
async function authenticated(event,newSession){
 if(!newSession){session=null;me=null;cache.clear();items=[];contacts=[];$('#modal').close();$('#lightbox').close();$('#profile-reminder').close();route='discover';render();showAuth();lastAuthToken='';return;}
 session=newSession;if(authRunning)return;if(lastAuthToken===newSession.access_token)return;
 authRunning=true;try{me=await api(event==='TOKEN_REFRESHED'?'me':'session',{event});nav();let accepted=false;try{accepted=sessionStorage.getItem('chich.adult.pending')==='yes';}catch{}if(accepted){await api('accept_adult');sessionStorage.removeItem('chich.adult.pending');await refreshMe();}$('#age-gate').close();await render();if(event!=='TOKEN_REFRESHED')reminder();lastAuthToken=newSession.access_token;}catch(e){$('#login-status').textContent=e.message;toast(e.message);showAuth();authStep(true);}finally{authRunning=false;}
}
async function nearby(){if(!navigator.geolocation)throw new Error('Trình duyệt không hỗ trợ vị trí.');modal('Tìm người ở gần',`<p>Cho phép truy cập vị trí để tìm những người cùng gu quanh bạn. Vị trí được làm tròn trước khi lưu; người khác chỉ thấy khoảng cách gần đúng. Thông tin tự hết hạn sau 24 giờ.</p><p>Bạn có thể tắt và xóa vị trí trong mục Riêng tư bất cứ lúc nào.</p><button class="button primary" data-action="allow-location">Cho phép và tìm quanh đây</button>`);}
async function locate(){const position=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,()=>reject(new Error('Chưa lấy được vị trí. Hãy kiểm tra quyền vị trí của trình duyệt.')),{enableHighAccuracy:false,timeout:15000,maximumAge:300000}));await api('location',{lat:position.coords.latitude,lon:position.coords.longitude});await refreshMe();filters.radius=25;$('#modal').close();go('discover');toast('Đã bật tìm người trong khoảng 25 km.');}
async function addMedia(files){if(!files.length||busy)return;const images=files.filter(f=>f.type.startsWith('image/')),videos=files.filter(f=>f.type.startsWith('video/'));if(images.length+(me.photos||[]).filter(x=>x.kind==='image').length>10||videos.length+(me.photos||[]).filter(x=>x.kind==='video').length>2)throw new Error('Mỗi hồ sơ tối đa 10 ảnh và 2 video.');for(const f of videos)if(!['video/mp4','video/webm'].includes(f.type)||f.size>20*1024*1024)throw new Error('Video phải là MP4/WebM, tối đa 20 MB.');busy=true;let done=0;try{for(const f of files){const blob=f.type.startsWith('image/')?(await preparePhoto(f)).blob:f;await upload(blob);done++;}toast(`Đã tải lên ${done} ảnh/video.`);}catch(e){toast(`${done?'Đã tải '+done+' file. ':''}${e.message}`);}finally{busy=false;await refreshMe();await render();}}
document.addEventListener('click',async event=>{
 const el=event.target.closest('button,[data-open]');if(!el)return;
 try{
 if(el.dataset.nav){$('#modal').close();go(el.dataset.nav);return;}
 if(el.dataset.open){await details(el.dataset.open);return;}
 if(el.dataset.galleryOwner){showGallery(el.dataset.galleryOwner,el.dataset.media);return;}
 if(el.dataset.step){galleryIndex+=Number(el.dataset.step);paintGallery();return;}
 if(el.dataset.body){filters.bodyType=el.dataset.body;render();return;}
 if(el.dataset.clearFilter){filters[el.dataset.clearFilter]='all';render();return;}
 if(el.dataset.like){const id=el.dataset.like;await api('like',{id,liked:!me.likes.includes(id)});await refreshMe();await render();toast('Đã cập nhật lượt thích.');if($('#modal').open)await details(id);return;}
 if(el.dataset.intro){modal('Một lời chào, một kết nối mới',`<form id="intro-form" data-id="${el.dataset.intro}"><label for="intro-text">Bạn muốn mở lời thế nào?</label><textarea id="intro-text" name="text" required maxlength="1000" placeholder="Chào bạn, mình thấy chúng ta cùng thích…"></textarea><button class="button primary" style="margin-top:18px">Gửi lời mở đầu ↗</button></form>`);return;}
 if(el.dataset.report){modal('Báo cáo hồ sơ',`<form id="report-form" data-id="${el.dataset.report}"><div class="field"><label for="report-reason">Lý do</label><select name="reason" id="report-reason">${options(['Giả mạo danh tính','Quấy rối hoặc ép buộc','Nghi ngờ chưa đủ 18 tuổi','Spam hoặc chào bán','Lý do khác'],'')}</select></div><div class="field"><label for="report-note">Mô tả thêm</label><textarea name="note" id="report-note" maxlength="500"></textarea></div><button class="button primary" style="margin-top:18px">Gửi báo cáo</button></form>`);return;}
 if(el.dataset.block){modal('Chặn hồ sơ này?',`<p>Hai bạn sẽ không thể tìm thấy nhau hoặc gửi tin nhắn cho nhau.</p><button class="button danger" data-confirm-block="${el.dataset.block}">Chặn hồ sơ</button>`);return;}
 if(el.dataset.confirmBlock){await api('block',{id:el.dataset.confirmBlock});$('#modal').close();cache.delete(el.dataset.confirmBlock);await refreshMe();await render();toast('Đã chặn hồ sơ.');return;}
 if(el.dataset.unblock){await api('unblock',{id:el.dataset.unblock});await render();return;}
 if(el.dataset.chat){chatId=el.dataset.chat;await render();return;}
 if(el.dataset.cover){await api('edit_media',{id:el.dataset.cover,cover:true});await refreshMe();await render();return;}
 if(el.dataset.delete){modal('Xóa ảnh/video?',`<p>File này sẽ được gỡ khỏi hồ sơ và kho lưu trữ.</p><button class="button danger" data-confirm-delete="${el.dataset.delete}">Xóa file</button>`);return;}
 if(el.dataset.confirmDelete){await removeMedia(el.dataset.confirmDelete);$('#modal').close();await refreshMe();await render();return;}
 if(el.dataset.resolve){await api('admin_resolve',{id:el.dataset.resolve,suspend:false});await render();return;}
 if(el.dataset.suspendReport){modal('Tạm khóa tài khoản?',`<p>Tài khoản bị báo cáo sẽ không thể sử dụng dịch vụ. Bạn có thể khôi phục trong cơ sở dữ liệu quản trị.</p><button class="button danger" data-confirm-suspend="${el.dataset.suspendReport}">Tạm khóa tài khoản</button>`);return;}
 if(el.dataset.confirmSuspend){await api('admin_resolve',{id:el.dataset.confirmSuspend,suspend:true});$('#modal').close();await render();return;}
 const action=el.dataset.action;
 if(action==='close')$('#modal').close();
 if(action==='close-gallery'){$('#lightbox').close();$('#lightbox-content').innerHTML='';}
 if(action==='complete-profile'){$('#profile-reminder').close();go('profile');}
 if(action==='remind-later')$('#profile-reminder').close();
 if(action==='preview-self')await details('self');
 if(action==='upload')$('#media-input').click();
 if(action==='explore'){if(!session)showAuth();else{$('#discover-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#query').focus({preventScroll:true});}}
 if(action==='toggle-filters'){filterOpen=!filterOpen;$('#advanced-filters').hidden=!filterOpen;el.setAttribute('aria-expanded',filterOpen);}
 if(action==='reset-filters'){filters=defaults();render();}
 if(action==='more')await results(true);
 if(action==='nearby')await nearby();
 if(action==='allow-location'){el.disabled=true;try{await locate();}finally{el.disabled=false;}}
 if(action==='location-off'){await api('location_off');filters.radius=0;await refreshMe();await render();toast('Đã tắt và xóa vị trí.');}
 if(action==='refresh-chat')await loadChat();
 if(action==='logout'){try{await api('logout');}catch{}await signOut();}
 if(action==='about')modal('CHI.CH DAO.',`<p>Cùng gu hình thể. Hợp gu hẹn hò.</p><p>Không gian hẹn hò nam–nam 18+ dành cho những người yêu sức hút khỏe khoắn — từ phòng tập đến những nhịp sống đời thường.</p><p>Nghề nghiệp và vóc dáng do mỗi người tự mô tả. Điều quan trọng là sự chân thành, tôn trọng và đồng thuận.</p>`);
 if(action==='privacy-info')modal('Quyền riêng tư',`<p>Hồ sơ, kết nối và tin nhắn được lưu để phục vụ việc làm quen. Ảnh và video trong hồ sơ có thể được xem bởi thành viên đăng nhập khi bạn bật hiển thị hồ sơ.</p><p>Đăng nhập Google chỉ dùng để xác thực tài khoản. Tên và ảnh Google không được tự động đưa vào hồ sơ hẹn hò.</p><p>Vị trí chỉ được lấy khi bạn cho phép, được làm tròn trước khi lưu và hết hạn sau 24 giờ. Người khác chỉ thấy nhóm khoảng cách, không thấy tọa độ hay ghim chính xác. Bạn có thể tắt và xóa vị trí trong mục Riêng tư.</p><p>Bạn có thể sửa hồ sơ, xóa từng ảnh/video, ẩn hồ sơ và chặn người khác. Tránh đưa số điện thoại, địa chỉ nhà hoặc lịch sinh hoạt chính xác vào hồ sơ.</p><p>Để bảo vệ cộng đồng và xử lý báo cáo, quản trị viên có thể truy cập hồ sơ, ảnh/video, tin nhắn và nhật ký hoạt động của tài khoản (thời điểm đăng nhập/đăng xuất, thiết bị, quốc gia/thành phố ước tính theo địa chỉ mạng). Mọi lượt truy cập của quản trị viên đều được ghi lại.</p><p>Phiên đăng nhập được lưu trên trình duyệt. Hãy đăng xuất khi dùng thiết bị chung.</p>`);
 if(action==='safety')modal('Sức hút bắt đầu từ sự tôn trọng',`<h3>18+ và đồng thuận</h3><p>Chỉ dành cho người từ 18 tuổi. Không quấy rối, ép buộc, miệt thị ngoại hình hoặc đăng ảnh người khác khi chưa được phép.</p><h3>Hồ sơ chân thật</h3><p>Sử dụng ảnh của bạn. Không giả mạo danh tính, spam hoặc dùng hẹn hò để ép mua dịch vụ.</p><h3>Chủ động bảo vệ mình</h3><p>Hỏi trước khi chia sẻ nội dung riêng tư. Ưu tiên địa điểm công cộng khi gặp lần đầu; không chuyển tiền chỉ vì lời hứa hẹn.</p><h3>Báo cáo và chặn</h3><p>Bạn có thể gửi báo cáo ở trang hồ sơ hoặc chặn người khiến bạn không thoải mái.</p>`);
 }catch(e){toast(e.message);}
});
document.addEventListener('input',e=>{
 if(e.target.id==='query'){filters.query=e.target.value.slice(0,100);clearTimeout(searchTimer);searchTimer=setTimeout(()=>results(),600);}
 if(['age-filter','min-age-filter'].includes(e.target.id)){if(e.target.id==='min-age-filter'){filters.minAge=Number(e.target.value);filters.maxAge=Math.max(filters.maxAge,filters.minAge);$('#age-filter').value=filters.maxAge;}else{filters.maxAge=Number(e.target.value);filters.minAge=Math.min(filters.minAge,filters.maxAge);$('#min-age-filter').value=filters.minAge;}$('#age-value').textContent=`${filters.minAge}–${filters.maxAge} tuổi`;clearTimeout(searchTimer);searchTimer=setTimeout(()=>results(),500);}
 if(e.target.id==='hero-image'){const file=e.target.files?.[0];if(file){const preview=$('.admin-hero-preview');if(preview.dataset.blob)URL.revokeObjectURL(preview.dataset.blob);preview.dataset.blob=URL.createObjectURL(file);preview.src=preview.dataset.blob;}}
});
document.addEventListener('change',async e=>{try{
 if(e.target.id==='city-filter'){filters.city=e.target.value;await results();}
 if(e.target.id==='intent-filter'){filters.intent=e.target.value;await results();}
 if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;await results();}
 if(e.target.id==='radius-filter'){filters.radius=Number(e.target.value);if(filters.radius&&!me?.nearbyEnabled){await nearby();return;}await results();}
 if(e.target.id==='visible-setting'){try{await api('visibility',{visible:e.target.checked});await refreshMe();toast('Đã cập nhật quyền hiển thị.');}catch(error){e.target.checked=!!me?.visible;throw error;}}
 if(e.target.id==='media-input'){const files=[...e.target.files];e.target.value='';await addMedia(files);}
 }catch(error){toast(error.message);}});
document.addEventListener('submit',async e=>{
 if(!['profile-form','message-form','intro-form','report-form','hero-form'].includes(e.target.id)&&!e.target.dataset.captionForm)return;
 e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));const button=form.querySelector('button[type="submit"],button');if(button?.disabled)return;if(button)button.disabled=true;
 try{
 if(form.id==='profile-form'){data.age=Number(data.age);if(!data.city||!data.intent)throw new Error('Chọn khu vực và mong muốn kết nối.');await api('profile_save',data);await refreshMe();await render();toast(me.complete?'Đã lưu hồ sơ. Bạn đã sẵn sàng kết nối.':'Đã lưu. Hãy thêm ít nhất một ảnh để hoàn thiện hồ sơ.');}
 if(form.id==='intro-form'||form.id==='message-form'){const id=form.id==='intro-form'?form.dataset.id:chatId;await api('send',{id,text:data.text});if(form.id==='intro-form'){$('#modal').close();chatId=id;go('messages');toast('Đã gửi lời mở đầu.');}else await loadChat();}
 if(form.id==='report-form'){await api('report',{id:form.dataset.id,...data});$('#modal').close();toast('Đã gửi báo cáo để quản trị viên xem xét.');}
 if(form.dataset.captionForm){await api('edit_media',{id:form.dataset.captionForm,caption:data.caption});await refreshMe();toast('Đã lưu chú thích.');}
 if(form.id==='hero-form'){const prepared=await preparePhoto(data.image);const id=await upload(prepared.blob,'hero');await api('admin_hero',{id,alt:data.alt});heroData=await hero();await render();toast('Đã thay ảnh hero trên trang chủ.');}
 }catch(error){toast(error.message);}finally{if(button)button.disabled=false;}
});
$('#age-check').addEventListener('change',e=>$('#enter-app').disabled=!e.target.checked);
$('#enter-app').addEventListener('click',()=>{if(!$('#age-check').checked)return;try{sessionStorage.setItem('chich.adult.pending','yes');}catch{toast('Cần cho phép lưu phiên để tiếp tục đăng nhập.');return;}authStep(true);});
$('#back-welcome').addEventListener('click',()=>authStep(false));
$('#underage').addEventListener('click',()=>{$('#age-check').checked=false;$('#enter-app').disabled=true;$('#age-note').textContent='Trang chỉ dành cho người từ 18 tuổi. Vui lòng đóng trang nếu bạn chưa đủ tuổi.';});
$('#email-login').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;$('#login-status').textContent='';try{await signInPassword(f.email.value,f.password.value);}catch(err){$('#login-status').textContent=err.message;}finally{b.disabled=false;}});
$('#google-login').addEventListener('click',async()=>{const b=$('#google-login');b.disabled=true;try{await signIn();}catch(e){$('#login-status').textContent=e.message;b.disabled=false;}});
$('#age-gate').addEventListener('cancel',e=>e.preventDefault());
$('#lightbox').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){galleryIndex+=e.key==='ArrowRight'?1:-1;paintGallery();}});
$('#lightbox').addEventListener('close',()=>$('#lightbox-content').innerHTML='');
document.addEventListener('keydown',e=>{if(e.target.matches('[data-open]')&&['Enter',' '].includes(e.key)){e.preventDefault();details(e.target.dataset.open).catch(e=>toast(e.message));}});
window.addEventListener('hashchange',()=>{if(location.hash==='#admin'){location.href='admin.html';return;}route=['discover','liked','messages','profile','settings','admin'].includes(location.hash.slice(1))?location.hash.slice(1):'discover';render();});
window.addEventListener('online',()=>{if(session)render();});
route=['discover','liked','messages','profile','settings','admin'].includes(location.hash.slice(1))?location.hash.slice(1):'discover';
render();showAuth();hero().then(data=>{heroData=data;if(route==='discover'&&data?.src){$('.hero-photo').src=data.src;$('.hero-photo').alt=data.alt;}}).catch(()=>{});
if(supabase){supabase.auth.onAuthStateChange((event,s)=>{setTimeout(()=>authenticated(event,s),0);});}
